/* ---- the table (second square of the grid). Its drawing: drag the coloured blocks out of their holes and put them anywhere -
   on the top, on the net (which gives a little under them), on the floor, or under the table where it hides them.
   Drop one near its hole and it drops back in. ---- */
(function(){
  var PIECES={"circle":[[283.7,553.4],[274.2,553.4],[267.2,552.8],[254.8,549.8],[248.3,547.4],[242.0,544.2],[237.7,541.4],[233.8,538.2],[230.2,534.5],[227.8,530.8],[225.8,526.0],[225.2,523.0],[225.4,518.2],[226.9,513.0],[229.6,508.3],[233.1,503.8],[237.2,500.4],[241.5,497.8],[246.3,495.4],[252.7,493.1],[259.2,491.2],[266.5,489.8],[272.5,488.9],[280.3,488.4],[286.5,488.4],[295.0,489.2],[307.0,492.2],[317.0,496.2],[323.3,500.1],[327.2,503.1],[330.8,506.7],[333.2,510.0],[335.1,513.5],[336.2,517.7],[336.2,523.7],[335.6,526.8],[333.6,531.3],[329.6,537.0],[326.0,540.4],[322.7,542.8],[318.5,545.1],[311.8,547.9],[299.3,551.4],[289.8,552.9]],"square":[[612.7,482.9],[569.8,440.5],[643.5,415.4],[685.9,457.8]],"triangle":[[638.0,340.4],[536.4,310.7],[631.3,274.2]]};   // outlines of the three blocks, traced from the drawing (0-1000 across the square)
  var TABLE={
    net:"data:image/webp;base64,",           // the drawing in two layers: the net on its own...
    tab:"data:image/webp;base64,",
    render:"data:image/webp;base64,",     // the rendered table, lined up with the drawing (click the table to see it)           // ...and everything else (top, legs, rails)
    top:[[28.7,560],[679,184.2],[949.3,340.7],[299,716.5]],   // the four corners of the table top
    netArea:[[394.2, 737.2], [366.5, 733.6], [321.9, 708.5], [861.5, 389.1], [863.3, 388.1], [865.4, 390.2], [882.4, 434.8], [883.0, 455.2]],     // the part of the net you can see
    H:168,   // height of the table top above the floor
    T:5.2,   // thickness of the top (and of the blocks)
    SAG:7,   // how far the net gives under a block
    bg:"#fafafa",
    pieces:{circle:{c:"#c6e2ff",smooth:1,p:PIECES.circle},square:{c:"#bb5e55",p:PIECES.square},triangle:{c:"#c8dcc2",p:PIECES.triangle}}
  };
  var st={},NS="http://www.w3.org/2000/svg";                     // where each block is (kept while the page is open)
  Object.keys(TABLE.pieces).forEach(function(k){st[k]={dx:0,dy:0,where:"seated",sag:0}});
  function cen(p){var x=0,y=0;p.forEach(function(q){x+=q[0];y+=q[1]});return[x/p.length,y/p.length]}
  function box(p){var a=[1e9,1e9,-1e9,-1e9];p.forEach(function(q){a[0]=Math.min(a[0],q[0]);a[1]=Math.min(a[1],q[1]);a[2]=Math.max(a[2],q[0]);a[3]=Math.max(a[3],q[1])});return a}
  function inPoly(pt,p){var c=false;for(var i=0,j=p.length-1;i<p.length;j=i++){var a=p[i],b=p[j];
    if((a[1]>pt[1])!==(b[1]>pt[1])&&pt[0]<(b[0]-a[0])*(pt[1]-a[1])/(b[1]-a[1])+a[0])c=!c}return c}
  function distPoly(pt,p){if(inPoly(pt,p))return 0;var m=1e9;for(var i=0,j=p.length-1;i<p.length;j=i++){var a=p[j],b=p[i],dx=b[0]-a[0],dy=b[1]-a[1],
    t=Math.max(0,Math.min(1,((pt[0]-a[0])*dx+(pt[1]-a[1])*dy)/(dx*dx+dy*dy||1)));m=Math.min(m,Math.hypot(pt[0]-a[0]-t*dx,pt[1]-a[1]-t*dy))}return m}
  function hull(pts){pts=pts.slice().sort(function(a,b){return a[0]-b[0]||a[1]-b[1]});
    function cr(o,a,b){return(a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])}
    var lo=[],up=[];pts.forEach(function(p){while(lo.length>1&&cr(lo[lo.length-2],lo[lo.length-1],p)<=0)lo.pop();lo.push(p)});
    pts.slice().reverse().forEach(function(p){while(up.length>1&&cr(up[up.length-2],up[up.length-1],p)<=0)up.pop();up.push(p)});
    return lo.slice(0,-1).concat(up.slice(0,-1))}
  function pstr(p,dx,dy){return p.map(function(q){return(q[0]+dx).toFixed(1)+","+(q[1]+dy).toFixed(1)}).join(" ")}
  function el(n,a,par){var e=document.createElementNS(NS,n);for(var k in a)e.setAttribute(k,a[k]);if(par)par.appendChild(e);return e}
  /* where a block lands: back in its hole, on the top, on the net, on the floor in front, or on the floor under / behind the table */
  function settle(k){var s=st[k],c=cen(TABLE.pieces[k].p),x=c[0]+s.dx,y=c[1]+s.dy;s.sag=0;
    if(Math.hypot(s.dx,s.dy)<22){s.dx=s.dy=0;s.where="seated";return}
    if(inPoly([x,y],TABLE.top)){s.where="top";return}
    if(distPoly([x,y],TABLE.netArea)<22){s.where="net";return}
    var A=TABLE.top[0],B=TABLE.top[1],D=TABLE.top[3],ux=B[0]-A[0],uy=B[1]-A[1],vx=D[0]-A[0],vy=D[1]-A[1],
        px=x-A[0],py=y-TABLE.H-A[1],det=ux*vy-uy*vx,u=(px*vy-py*vx)/det,v=(ux*py-uy*px)/det;   // the point of the top straight above it
    s.where=(u>0&&v<1)?"under":"floor"}
  function drawPiece(k,g,lift){var s=st[k],pc=TABLE.pieces[k],P=pc.p,dx=s.dx,dy=s.dy+(s.where==="net"&&!lift?s.sag:0),T=TABLE.T,grp=el("g",{"class":"tpc","data-k":k},g);
    if(s.where==="seated"&&!lift){                                  // in its hole: flush with the top, just a hint of shadow
      el("polygon",{points:pstr(P,dx+.8,dy+1.4),"class":"tsh seat"},grp);
      el("polygon",{points:pstr(P,dx,dy),fill:pc.c,"class":"ttop"},grp);return}
    var up=T+(lift||0),sh=lift?{o:.16,b:"url(#tblurL)",x:6,y:9}:s.where==="net"?{o:.12,b:"url(#tblur)",x:1.5,y:2.5}:{o:.22,b:"url(#tblur)",x:2.5,y:3.5};
    el("polygon",{points:pstr(P,dx+sh.x,dy+sh.y),fill:"#000","fill-opacity":sh.o,filter:sh.b,"class":"tsh"},grp);   // its little shadow
    var topP=P.map(function(q){return[q[0]+dx,q[1]+dy-up]}),bot=P.map(function(q){return[q[0]+dx,q[1]+dy-up+T]}),H=hull(topP.concat(bot));
    el("polygon",{points:pstr(H,0,0),fill:"#fff","class":"tln"},grp);   // its edge, as thick as the table top
    if(!pc.smooth){var Hs=H.map(String);bot.forEach(function(b,i){if(Hs.indexOf(String(b))>=0)el("line",{x1:topP[i][0],y1:topP[i][1],x2:b[0],y2:b[1],"class":"tln"},grp)})}
    el("polygon",{points:pstr(topP,0,0),fill:pc.c,"class":"ttop"},grp)}
  /* the net giving under a block: the net itself is pulled down around it (a smooth dip, no gaps - the net runs on under the top) */
  function dipMap(k){var s=st[k],P=TABLE.pieces[k].p,b=box(P),c=cen(P),cx=c[0]+s.dx,cy=c[1]+s.dy+2,rx=(b[2]-b[0])*.9+22,ry=rx*.55,
      W=96,H=56,cv=document.createElement("canvas");cv.width=W;cv.height=H;var g=cv.getContext("2d"),im=g.createImageData(W,H),q=s.sag/TABLE.SAG;
    for(var y=0;y<H;y++)for(var x=0;x<W;x++){var dx=(x+.5)/W*2-1,dy=(y+.5)/H*2-1,r=Math.sqrt(dx*dx+dy*dy),f=r<1?.5*(1+Math.cos(Math.PI*r)):0,i=(y*W+x)*4;
      im.data[i]=128;im.data[i+1]=Math.round(128-127*f*q);im.data[i+2]=128;im.data[i+3]=255}
    g.putImageData(im,0,0);return{href:cv.toDataURL(),x:cx-rx,y:cy-ry,w:2*rx,h:2*ry}}
  function dips(svg){var net=svg.querySelector(".tnet"),old=svg.querySelector("#tdisp");if(old)old.remove();
    var ks=Object.keys(st).filter(function(k){return st[k].where==="net"&&st[k].sag>0});
    if(!ks.length){net.removeAttribute("filter");return}
    var f=el("filter",{id:"tdisp",filterUnits:"userSpaceOnUse",x:0,y:0,width:1000,height:1100,"color-interpolation-filters":"sRGB"},svg.querySelector("defs"));
    el("feFlood",{"flood-color":"rgb(128,128,128)",result:"m0"},f);
    ks.forEach(function(k,i){var m=dipMap(k);el("feImage",{href:m.href,x:m.x,y:m.y,width:m.w,height:m.h,preserveAspectRatio:"none",result:"d"+i},f);
      el("feComposite",{"in":"d"+i,in2:"m"+i,operator:"over",result:"m"+(i+1)},f)});
    el("feDisplacementMap",{"in":"SourceGraphic",in2:"m"+ks.length,scale:2*TABLE.SAG,xChannelSelector:"R",yChannelSelector:"G"},f);
    net.setAttribute("filter","url(#tdisp)")}
  window.tableScene=function(boxEl){
    var dragK=null;
    var svg=el("svg",{viewBox:"-61 -40 1100 1100","aria-label":"The table: drag the coloured blocks"},boxEl);
    svg.innerHTML='<defs><filter id="tblur" x="-30%" y="-30%" width="160%" height="160%"><feGaussianBlur stdDeviation="3"/></filter>'+
      '<filter id="tblurL" x="-40%" y="-40%" width="180%" height="180%"><feGaussianBlur stdDeviation="7"/></filter>'+
      '<radialGradient id="tdg"><stop offset="0" stop-color="#fff"/><stop offset=".55" stop-color="#fff"/><stop offset="1" stop-color="#000"/></radialGradient></defs>'+
      '<g class="ldefs"></g><g class="lunder"></g><image class="tnet" href="'+TABLE.net+'" width="1000" height="1000" pointer-events="none"/>'+
      '<g class="ldent"></g><g class="lnet"></g><image href="'+TABLE.tab+'" width="1000" height="1000" pointer-events="none"/><polygon class="thit" points="'+pstr(TABLE.top,0,0)+'"/><g class="lfloor"></g><g class="ltop"></g>'+
      '<image class="trender" href="'+TABLE.render+'" x="-61" y="-40" width="1100" height="1100" pointer-events="none"/>';
    var defs=svg.querySelector("defs"),L={under:svg.querySelector(".lunder"),dent:svg.querySelector(".ldent"),net:svg.querySelector(".lnet"),floor:svg.querySelector(".lfloor"),top:svg.querySelector(".ltop")};
    function render(){for(var n in L)L[n].innerHTML="";[].slice.call(defs.querySelectorAll("mask")).forEach(function(m){m.remove()});
      Object.keys(st).sort(function(a,b){return(cen(TABLE.pieces[a].p)[1]+st[a].dy)-(cen(TABLE.pieces[b].p)[1]+st[b].dy)})
        .forEach(function(k){if(k===dragK)return;var w=st[k].where;drawPiece(k,L[w==="seated"?"top":w])});
      dips(svg);
      if(dragK)drawPiece(dragK,L.top,14)}                            // the one in your hand: lifted, on top of everything
    render();
    /* dropped on the net: it sinks in, bounces a little and settles */
    function give(k){var t0=performance.now(),S=TABLE.SAG;(function f(now){var s=st[k];if(s.where!=="net"||dragK===k){s.sag=0;return}
      var t=now-t0;s.sag=S*(1-Math.exp(-t/170)*Math.cos(t/75));render();if(t<1200)requestAnimationFrame(f);else{s.sag=S;render()}})(t0)}
    function pt(e){var p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform(svg.getScreenCTM().inverse())}
    var d=null;
    svg.addEventListener("pointerdown",function(e){var g=e.target.closest&&e.target.closest(".tpc");if(!g||svg.classList.contains("rendered"))return;e.preventDefault();e.stopPropagation();
      var k=g.getAttribute("data-k"),p=pt(e);dragK=k;st[k].sag=0;d={k:k,x:p.x,y:p.y,dx:st[k].dx,dy:st[k].dy};svg.setPointerCapture(e.pointerId);svg.classList.add("dragging");render()});
    svg.addEventListener("pointermove",function(e){if(!d)return;var p=pt(e),s=st[d.k],c=cen(TABLE.pieces[d.k].p);
      s.dx=Math.max(-c[0]-25,Math.min(1010-c[0],d.dx+p.x-d.x));s.dy=Math.max(-c[1]+20,Math.min(1040-c[1],d.dy+p.y-d.y));render()});
    var moved=0;function up(){if(!d)return;moved=Date.now();var k=d.k;settle(k);d=null;dragK=null;svg.classList.remove("dragging");render();if(st[k].where==="net")give(k)}
    svg.addEventListener("pointerup",up);svg.addEventListener("pointercancel",up);
    svg.addEventListener("click",function(e){if(e.target.closest&&e.target.closest(".tpc")&&!svg.classList.contains("rendered")){e.stopPropagation();return}
      if(Date.now()-moved<300)return;                                              // the end of a drag is not a click
      if(svg.classList.contains("rendered")){svg.classList.remove("rendered");e.stopPropagation();return}   // click the render: back to the drawing
      if(e.target.closest&&e.target.closest(".thit")){svg.classList.add("rendered");e.stopPropagation()}});   // click the table: the render
  };
})();
